mapper.select:
SELECT zkpid, zkpmc, zkpmc AS zwmc, pym, zkplx, xmdm, xmzwmc, bjzl, bjzh, sccj, sxrq, zxbz, sybz FROM sys_zkpd WHERE 1=1 AND sb_djid = #{sbDjid}
AND (zkpmc LIKE CONCAT('%',#{keyword},'%') OR xmzwmc LIKE CONCAT('%',#{keyword},'%'))
ORDER BY zkpid DESC

mapper.update:
UPDATE sys_zkpd
SET sb_djid=#{sbDjid}, zwmc=#{zwmc}, ywmc=#{ywmc}, zkpsm=#{zkpsm}, ph=#{ph}, sccj=#{sccj}, sybz=#{sybz}
WHERE zkpid=#{zkpid}
